<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { useForm, usePage } from '@inertiajs/vue3';

const props = defineProps<{profile:{name:string;username?:string;email:string;phone?:string;avatar_path?:string}}>();
const page = usePage<any>();
const form = useForm<{name:string;email:string;phone:string;avatar:File|null}>({name:props.profile.name,email:props.profile.email,phone:props.profile.phone??'',avatar:null});
const submit=()=>form.post('/profil',{forceFormData:true,preserveScroll:true});
</script>
<template><AppLayout title="Profil Saya"><main class="view space-y-6"><section class="hero-card compact-hero"><div><p class="eyebrow">Akun pribadi</p><h1>Profil saya</h1><p>Perbarui identitas kontak dan foto akun Anda.</p></div><a class="secondary-button" href="/ganti-password">Ganti kata sandi</a></section><div v-if="page.props.flash?.message" class="notice success">{{ page.props.flash.message }}</div><section class="panel profile-panel"><form class="profile-form" @submit.prevent="submit"><div class="avatar-preview"><img v-if="page.props.auth?.user?.avatar_url" :src="page.props.auth.user.avatar_url" alt="Foto profil"><span v-else>{{ form.name.slice(0,2).toUpperCase() }}</span></div><label>Foto profil<input type="file" accept="image/jpeg,image/png,image/webp" @input="form.avatar=($event.target as HTMLInputElement).files?.[0]??null"><small>JPG, PNG, atau WebP; maksimum 2 MB.</small><em v-if="form.errors.avatar">{{ form.errors.avatar }}</em></label><label>Nama lengkap<input v-model="form.name" required><em v-if="form.errors.name">{{ form.errors.name }}</em></label><label>Username<input :value="profile.username" disabled><small>Username dikelola administrator.</small></label><label>Email<input v-model="form.email" type="email" required><em v-if="form.errors.email">{{ form.errors.email }}</em></label><label>Nomor kontak<input v-model="form.phone" type="tel"><em v-if="form.errors.phone">{{ form.errors.phone }}</em></label><button class="primary-button" :disabled="form.processing">{{ form.processing?'Menyimpan…':'Simpan profil' }}</button></form></section></main></AppLayout></template>
<style scoped>.profile-panel{max-width:720px;padding:1.5rem}.profile-form{display:grid;gap:1rem}.profile-form label{display:grid;gap:.4rem;font-size:.78rem;font-weight:800}.profile-form input{border:1px solid var(--line);border-radius:.7rem;padding:.75rem}.profile-form small{color:var(--ink-soft);font-weight:500}.profile-form em{color:var(--red);font-style:normal}.avatar-preview{width:88px;height:88px;border-radius:24px;overflow:hidden;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-size:1.4rem;font-weight:900}.avatar-preview img{width:100%;height:100%;object-fit:cover}.primary-button{justify-self:start}</style>
